const recoverStuckDocuments = `-- name: RecoverStuckDocuments :execrows
UPDATE documents SET status = 'pending', updated_at = now()
WHERE status IN ('queued', 'processing') AND updated_at < now() - make_interval(mins => $1::int)
`

// Documents stuck in queued/processing (e.g. job lost) go back to pending.
func (q *Queries) RecoverStuckDocuments(ctx context.Context, olderThanMinutes int32) (int64, error) {
	result, err := q.db.Exec(ctx, recoverStuckDocuments, olderThanMinutes)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

