const searchDocuments = `-- name: SearchDocuments :many
SELECT id, source_id, team_id, external_id, title, filename, url, kind, content_type, size_bytes, sha256, version, blob_key, status, error_code, error_message, parser, pages, warnings, chunk_count, token_count, metadata, tags, acl, attempts, uploaded_by, created_at, updated_at, processed_at, http_etag, http_last_modified, last_seen_crawl_id, waiting_until FROM documents
WHERE source_id = $1
  AND (title || ' ' || url || ' ' || filename) ILIKE '%' || $2::text || '%' ESCAPE '\'
  AND ($3::text IS NULL OR status = $3::text)
  AND ($4::text IS NULL OR kind = $4::text)
  AND ($5::text IS NULL OR tags @> ARRAY[lower($5::text)])
  AND ($6::text IS NULL OR error_code = $6::text)
  AND ($7::timestamptz IS NULL
       OR (created_at, id) < ($7::timestamptz, $8::uuid))
ORDER BY created_at DESC, id DESC
LIMIT $9
`

type SearchDocumentsParams struct {
	SourceID      uuid.UUID
	Search        string
	Status        *string
	Kind          *string
	Tag           *string
	ErrorCode     *string
	BeforeCreated *time.Time
	BeforeID      uuid.NullUUID
	PageSize      int32
}

// ListDocuments filtered by text. A separate query (no "IS NULL OR") so the
// planner can always use documents_search_idx, whose expression this repeats.
// The search text is LIKE-escaped by the caller.
func (q *Queries) SearchDocuments(ctx context.Context, arg SearchDocumentsParams) ([]Document, error) {
	rows, err := q.db.Query(ctx, searchDocuments,
		arg.SourceID,
		arg.Search,
		arg.Status,
		arg.Kind,
		arg.Tag,
		arg.ErrorCode,
		arg.BeforeCreated,
		arg.BeforeID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Document{}
	for rows.Next() {
		var i Document
		if err := rows.Scan(
			&i.ID,
			&i.SourceID,
			&i.TeamID,
			&i.ExternalID,
			&i.Title,
			&i.Filename,
			&i.URL,
			&i.Kind,
			&i.ContentType,
			&i.SizeBytes,
			&i.Sha256,
			&i.Version,
			&i.BlobKey,
			&i.Status,
			&i.ErrorCode,
			&i.ErrorMessage,
			&i.Parser,
			&i.Pages,
			&i.Warnings,
			&i.ChunkCount,
			&i.TokenCount,
			&i.Metadata,
			&i.Tags,
			&i.Acl,
			&i.Attempts,
			&i.UploadedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ProcessedAt,
			&i.HttpEtag,
			&i.HttpLastModified,
			&i.LastSeenCrawlID,
			&i.WaitingUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

